create or replace view public.v_production_yield_learning as
select r.id as recipe_id,r.business_code as recipe_code,r.name as recipe_name,r.output_item_id,rv.id as recipe_version_id,rv.version_number,rv.expected_output_quantity as recipe_expected_output,rv.output_unit_id,count(pb.id)::integer as completed_batches,round(coalesce(avg(pb.actual_output_quantity/nullif(pb.planned_output_quantity,0))*100,100),2) as learned_yield_percent,round(coalesce(avg(pb.actual_output_quantity/nullif(pb.planned_output_quantity,0)),1),6) as learned_yield_factor,round(rv.expected_output_quantity*coalesce(avg(pb.actual_output_quantity/nullif(pb.planned_output_quantity,0)),1),3) as learned_expected_output
from public.recipes r join public.recipe_versions rv on rv.recipe_id=r.id left join public.production_batches pb on pb.recipe_version_id=rv.id and pb.status='completed' and pb.actual_output_quantity is not null and pb.planned_output_quantity>0
group by r.id,r.business_code,r.name,r.output_item_id,rv.id,rv.version_number,rv.expected_output_quantity,rv.output_unit_id;
